CREATE TABLE profit_confirmation(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,order_id uuid NOT NULL,request_key uuid NOT NULL,version integer NOT NULL,net_original numeric(19,4) NOT NULL,currency text NOT NULL,exchange_rate numeric(19,8) NOT NULL,purchase_cny numeric(19,4) NOT NULL,freight_cny numeric(19,4) NOT NULL,platform_cny numeric(19,4) NOT NULL,contribution_cny numeric(19,2) NOT NULL,source text NOT NULL,actor text NOT NULL,confirmed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,request_key),UNIQUE(tenant_id,order_id,version),FOREIGN KEY(tenant_id,order_id) REFERENCES sales_order(tenant_id,id));
CREATE FUNCTION immutable_profit_confirmation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Profit confirmations are immutable; append a new version';END $$;
CREATE TRIGGER immutable_profit_confirmation BEFORE UPDATE OR DELETE ON profit_confirmation FOR EACH ROW EXECUTE FUNCTION immutable_profit_confirmation();
